/**
 * Generate Database types from local Supabase into src/types/database.generated.ts
 */
import { execSync } from 'node:child_process';
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outPath = resolve(root, 'src/types/database.generated.ts');

mkdirSync(dirname(outPath), { recursive: true });

const header = `/**
 * AUTO-GENERATED by scripts/gen-db-types.mjs — do not edit by hand.
 * Source: local Supabase schema (npx supabase gen types typescript --local)
 */
`;

console.log('Generating types from local Supabase…');
const types = execSync('npx supabase gen types typescript --local', {
  cwd: root,
  encoding: 'utf8',
  stdio: ['ignore', 'pipe', 'pipe'],
  maxBuffer: 20 * 1024 * 1024,
});

writeFileSync(outPath, header + types, 'utf8');
console.log(`Wrote ${outPath}`);
